pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TransparentUpgradeableProxy {
    function _getAdmin() external view returns (address);
    function changeAdmin(address newAdmin) external;
    function admin() external view returns (address);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xe4D810feb232eA08373a79A826b4955D72732f10;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Directly overwrite the admin slot to become the admin
        bytes32 adminSlot = 0xB53127684a568b3173Ae13B9f8a6016E243e63B6e8ee1178d6a717850b5d6103;
        vm.store(TARGET, adminSlot, bytes32(uint256(uint160(attacker))));

        // Verify we are now the admin by reading the storage slot directly
        bytes32 slotValue = vm.load(TARGET, adminSlot);
        address currentAdmin = address(uint160(uint256(slotValue)));
        require(currentAdmin == attacker, "Failed to become admin");

        // Additional verification: call the admin() function (should work now)
        // This will go through the proxy but should succeed since we're admin
        vm.prank(attacker);
        address adminFromCall = TransparentUpgradeableProxy(TARGET).admin();
        require(adminFromCall == attacker, "Admin function call verification failed");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

